using DrawVerify.Core.Authorization;
using DrawVerify.Core.Interfaces;
using DrawVerify.Core.Models;
namespace DrawVerify.Application.Services;
public sealed class ReportTemplateService : IReportTemplateService
{
    private readonly IReportTemplateRepository _repository; private readonly ISessionAuthenticationService _session; private readonly RoleAuthorization _authorization; private readonly ICentralizedLogger? _logger;
    public ReportTemplateService(IReportTemplateRepository repository, ISessionAuthenticationService session, RoleAuthorization authorization, ICentralizedLogger? logger = null) { _repository = repository; _session = session; _authorization = authorization; _logger = logger; }
    private string Actor() { if (!_session.IsAuthenticated || !_authorization.IsAllowed(_session.CurrentUser, RolePermission.ManageGlobalConfiguration)) throw new UnauthorizedAccessException("Only an authenticated Admin can manage report templates."); return _session.CurrentUser!.UserId; }
    public Task<IReadOnlyList<ReportTemplate>> ListAsync(CancellationToken cancellationToken = default) { Actor(); return _repository.ListAsync(cancellationToken); }
    public Task<ReportTemplate> CreateAsync(string name, string actorId, CancellationToken cancellationToken = default) { var actor = Actor(); return SaveCore(new ReportTemplate { Name = name }, 0, actor, "Created", cancellationToken); }
    public async Task<ReportTemplate> DuplicateAsync(Guid id, string name, string actorId, CancellationToken cancellationToken = default) { var actor = Actor(); var source = await _repository.GetAsync(id, cancellationToken: cancellationToken) ?? throw new InvalidOperationException("Template was not found."); return await SaveCore(source with { Id = Guid.NewGuid(), Name = name, Version = 1, IsOrganizationDefault = false }, 0, actor, "Created", cancellationToken); }
    public Task<ReportTemplate> SaveAsync(ReportTemplate template, int expectedVersion, string actorId, CancellationToken cancellationToken = default) { var actor = Actor(); return SaveCore(template, expectedVersion, actor, expectedVersion == 0 ? "Created" : "Modified", cancellationToken); }
    private Task<ReportTemplate> SaveCore(ReportTemplate template, int expectedVersion, string actorId, string action, CancellationToken token) { var authenticatedActor = Actor(); ReportTemplateValidator.Validate(template); var audit = new ReportTemplateAuditEntry { TemplateId = template.Id, Version = template.Version, ActorId = authenticatedActor, Action = action, Summary = template.Name }; return _repository.SaveAsync(template, expectedVersion, audit, token); }
    public async Task SetDefaultAsync(Guid id, string actorId, CancellationToken cancellationToken = default) { var actor = Actor(); var template = await _repository.GetAsync(id, cancellationToken: cancellationToken) ?? throw new InvalidOperationException("Template was not found."); await _repository.SetDefaultAsync(id, new ReportTemplateAuditEntry { TemplateId = id, Version = template.Version, ActorId = actor, Action = "DefaultChanged", Summary = "Organization default changed" }, cancellationToken); }
    public Task DeleteAsync(Guid id, int expectedVersion, string actorId, CancellationToken cancellationToken = default) { var actor = Actor(); return _repository.DeleteAsync(id, expectedVersion, new ReportTemplateAuditEntry { TemplateId = id, Version = expectedVersion, ActorId = actor, Action = "Deleted" }, cancellationToken); }
    public Task<IReadOnlyList<ReportTemplateVersion>> GetVersionsAsync(Guid id, CancellationToken cancellationToken = default) { Actor(); return _repository.GetVersionsAsync(id, cancellationToken); }
    public async Task<ReportTemplate> RestoreAsync(Guid id, int version, string actorId, CancellationToken cancellationToken = default) { var actor = Actor(); var snapshot = await _repository.GetAsync(id, version, cancellationToken) ?? throw new InvalidOperationException("Template version was not found."); var current = await _repository.GetAsync(id, cancellationToken: cancellationToken) ?? throw new InvalidOperationException("Template was not found."); return await SaveCore(snapshot with { Version = current.Version + 1, IsOrganizationDefault = current.IsOrganizationDefault }, current.Version, actor, "Restored", cancellationToken); }
    public async Task AssignAsync(ReportTemplateAssignment assignment, string actorId, CancellationToken cancellationToken = default) { var actor = Actor(); if (assignment.ProjectId is null && assignment.WorkflowId is null) throw new InvalidOperationException("A project or workflow scope is required."); var template = await _repository.GetAsync(assignment.TemplateId, cancellationToken: cancellationToken) ?? throw new InvalidOperationException("Template was not found."); await _repository.AssignAsync(assignment, new ReportTemplateAuditEntry { TemplateId = assignment.TemplateId, Version = template.Version, ActorId = actor, Action = "Assigned", Summary = $"Project={assignment.ProjectId}; Workflow={assignment.WorkflowId}" }, cancellationToken); }
}
